import{_ as s,o as e,c as t,a2 as n}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_map_dataflow_cover.png",o="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_map_dataflow_01_architecture.png",p="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_map_dataflow_02_static_map.png",i="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_map_dataflow_03_global.png",c="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_map_dataflow_04_local.png",r="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_map_dataflow_05_update_publish.png",d="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_map_dataflow_06_interfaces.png",C=JSON.parse('{"title":"Nav2 的两张地图怎样驱动规划与控制？全局与局部 Costmap 全数据流拆解","description":"在 Nav2 中，“地图”至少有三种含义。","frontmatter":{"title":"Nav2 的两张地图怎样驱动规划与控制？全局与局部 Costmap 全数据流拆解","description":"在 Nav2 中，“地图”至少有三种含义。","date":"2026-07-17","topic":"Nav2 工程实践","section":"一 · 架构与启动","readingTime":9,"source":"2026-07-17/nav2_global_local_map_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-17/nav2_map_dataflow_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-global-local-map-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Nav2 的两张地图怎样驱动规划与控制？全局与局部 Costmap 全数据流拆解"}],["meta",{"property":"og:description","content":"在 Nav2 中，“地图”至少有三种含义。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-global-local-map-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-17/nav2_map_dataflow_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-17"}],["meta",{"name":"twitter:title","content":"Nav2 的两张地图怎样驱动规划与控制？全局与局部 Costmap 全数据流拆解"}],["meta",{"name":"twitter:description","content":"在 Nav2 中，“地图”至少有三种含义。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-17/nav2_map_dataflow_cover.png"}]],"prev":{"text":"一张 PGM 地图怎样进入 Nav2？拆解 `nav2_map_server` 调用全数据流","link":"/nav2/nav2-map-server-full-dataflow"},"next":{"text":"砍掉行为树之后，Nav2 还能怎么跑？一套自研规控导航的状态机与全数据流拆解","link":"/nav2/nav2-regulated-no-bt-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-global-local-map-full-dataflow.md","filePath":"nav2/nav2-global-local-map-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/nav2-global-local-map-full-dataflow.md"};function m(u,a,b,g,_,v){return e(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="nav2-的两张地图怎样驱动规划与控制-全局与局部-costmap-全数据流拆解" tabindex="-1">Nav2 的两张地图怎样驱动规划与控制？全局与局部 Costmap 全数据流拆解 <a class="header-anchor" href="#nav2-的两张地图怎样驱动规划与控制-全局与局部-costmap-全数据流拆解" aria-label="Permalink to &quot;Nav2 的两张地图怎样驱动规划与控制？全局与局部 Costmap 全数据流拆解&quot;">​</a></h1><p><img src="'+l+`" alt="封面：Nav2 全局与局部地图数据流"></p><p>在 Nav2 中，“地图”至少有三种含义。</p><p>第一种是磁盘里的 YAML 和 PGM／PNG，它描述静态世界；第二种是 <code>/map</code> 上的 <code>OccupancyGrid</code>，它是 ROS 2 能传输的静态占用栅格；第三种是 Planner 和 Controller 真正使用的 Costmap，它把静态地图、实时传感器、机器人位姿、Footprint 和语义过滤器融合成不断变化的风险场。</p><p>最容易产生误解的地方是：全局地图和局部地图并不是两个 Map Server，也不是 Planner、Controller 分别订阅一张图片。</p><p>真实关系是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Map Server 发布 /map</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>Global Costmap 与 Local Costmap 各自按配置融合数据</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>Planner 直接读取 Global Master Costmap</span></span>
<span class="line"><span>Controller 直接读取 Local Master Costmap</span></span></code></pre></div><p>本文基于当前 <code>navigation2/</code> 源码，把磁盘地图、Map Server、Static Layer、Obstacle Layer、Layered Costmap、Planner Server、Controller Server以及全部外部接口串成一条完整数据流。</p><p><img src="`+o+'" alt="图 1：Nav2 地图系统总架构"></p><h2 id="一、先给结论-nav2-同时维护-静态世界-和-两张风险地图" tabindex="-1">一、先给结论：Nav2 同时维护“静态世界”和“两张风险地图” <a class="header-anchor" href="#一、先给结论-nav2-同时维护-静态世界-和-两张风险地图" aria-label="Permalink to &quot;一、先给结论：Nav2 同时维护“静态世界”和“两张风险地图”&quot;">​</a></h2><p>磁盘地图只负责提供长期不变的环境底图：墙、固定障碍、未知区和可通行区域。</p><p>Global Costmap 面向全局路径搜索，通常覆盖整张地图，重点回答：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从当前位置到目标点，哪条长距离路线可以走？</span></span></code></pre></div><p>Local Costmap 面向实时运动控制，通常是以机器人为中心的滚动窗口，重点回答：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>未来几秒怎样运动，才不会撞上眼前障碍？</span></span></code></pre></div><p>二者都可以使用 <code>nav2_costmap_2d</code> 的 Layer 插件，但窗口、坐标系、频率和传感器范围通常不同。为了适配微信公众号手机端阅读，关键差异改用分组条目呈现。</p><h3 id="_1-1-global-costmap" tabindex="-1">1.1 Global Costmap <a class="header-anchor" href="#_1-1-global-costmap" aria-label="Permalink to &quot;1.1 Global Costmap&quot;">​</a></h3><ul><li>所有者：Planner Server。</li><li>主要消费者：全局规划插件。</li><li>常见窗口：固定整图。</li><li>常见输入：<code>/map</code>、TF 和较远障碍。</li><li>主要目标：路径可达性与全局绕行。</li><li>常见更新频率：较低。</li></ul><h3 id="_1-2-local-costmap" tabindex="-1">1.2 Local Costmap <a class="header-anchor" href="#_1-2-local-costmap" aria-label="Permalink to &quot;1.2 Local Costmap&quot;">​</a></h3><ul><li>所有者：Controller Server。</li><li>主要消费者：局部控制插件。</li><li>常见窗口：机器人中心滚动窗口。</li><li>常见输入：TF 和近场 LaserScan／PointCloud2。</li><li>主要目标：轨迹碰撞与实时避障。</li><li>常见更新频率：较高。</li></ul><h2 id="二、第一段主链-磁盘地图怎样变成-map" tabindex="-1">二、第一段主链：磁盘地图怎样变成 <code>/map</code> <a class="header-anchor" href="#二、第一段主链-磁盘地图怎样变成-map" aria-label="Permalink to &quot;二、第一段主链：磁盘地图怎样变成 `/map`&quot;">​</a></h2><p>Map Server 不直接把图片字节发给导航系统。它先把 YAML 和图像翻译成 <code>nav_msgs/msg/OccupancyGrid</code>。</p><p><img src="'+p+`" alt="图 2：磁盘地图到 Static Layer 的完整链路"></p><h3 id="_2-1-yaml-是地图的解释规则" tabindex="-1">2.1 YAML 是地图的解释规则 <a class="header-anchor" href="#_2-1-yaml-是地图的解释规则" aria-label="Permalink to &quot;2.1 YAML 是地图的解释规则&quot;">​</a></h3><p>典型 YAML 包含：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">map.pgm</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">trinary</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">resolution</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.05</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">origin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-10.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-10.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">negate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">occupied_thresh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.65</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">free_thresh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.25</span></span></code></pre></div><p><code>resolution</code> 决定每个像素代表多少米；<code>origin</code> 决定图片左下角在 <code>map</code> 坐标系中的位置；两个阈值决定灰度怎样解释为占用和空闲。</p><h3 id="_2-2-map-io-完成像素到栅格的翻译" tabindex="-1">2.2 <code>map_io</code> 完成像素到栅格的翻译 <a class="header-anchor" href="#_2-2-map-io-完成像素到栅格的翻译" aria-label="Permalink to &quot;2.2 \`map_io\` 完成像素到栅格的翻译&quot;">​</a></h3><p><code>map_io</code> 读取图片宽高和颜色，计算占用概率，再生成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0    空闲</span></span>
<span class="line"><span>100  占用</span></span>
<span class="line"><span>-1   未知</span></span></code></pre></div><p>图像以左上角为常见原点，OccupancyGrid 以地图左下角组织，因此转换过程中会做 Y 轴翻转。图片能打开，不等于坐标语义一定正确；分辨率、原点和 Y 轴任一错误，最终路径都会整体偏移。</p><h3 id="_2-3-map-server-缓存并发布" tabindex="-1">2.3 Map Server 缓存并发布 <a class="header-anchor" href="#_2-3-map-server-缓存并发布" aria-label="Permalink to &quot;2.3 Map Server 缓存并发布&quot;">​</a></h3><p>Map Server 在 Lifecycle <code>configure</code> 阶段读取地图并写入 <code>msg_</code> 缓存，在 <code>activate</code> 阶段激活 Publisher 并发布。</p><p><code>/map</code> 通常采用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KeepLast(1)</span></span>
<span class="line"><span>reliable</span></span>
<span class="line"><span>transient_local</span></span></code></pre></div><p>因此后启动的 Static Layer 仍能收到最近一次地图。</p><p>Map Server 还提供：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/&lt;map_server&gt;/map       nav_msgs/srv/GetMap</span></span>
<span class="line"><span>/&lt;map_server&gt;/load_map  nav2_msgs/srv/LoadMap</span></span>
<span class="line"><span>/map                    nav_msgs/msg/OccupancyGrid</span></span></code></pre></div><p>Map Saver 则反向临时订阅某个 OccupancyGrid Topic，把消息写回图片和 YAML。</p><h2 id="三、global-costmap-整张静态地图怎样变成规划风险场" tabindex="-1">三、Global Costmap：整张静态地图怎样变成规划风险场 <a class="header-anchor" href="#三、global-costmap-整张静态地图怎样变成规划风险场" aria-label="Permalink to &quot;三、Global Costmap：整张静态地图怎样变成规划风险场&quot;">​</a></h2><p>Planner Server 在构造阶段创建名为 <code>global_costmap</code> 的 <code>Costmap2DROS</code>。这张图不是独立进程里的一份远程数据，而是 Planner Server 拥有的运行时对象。</p><p><img src="`+i+`" alt="图 3：Global Costmap 到全局路径的数据流"></p><h3 id="_3-1-static-layer-接收-map" tabindex="-1">3.1 Static Layer 接收 <code>/map</code> <a class="header-anchor" href="#_3-1-static-layer-接收-map" aria-label="Permalink to &quot;3.1 Static Layer 接收 \`/map\`&quot;">​</a></h3><p>Static Layer 订阅完整 <code>/map</code>，也可以选择订阅 <code>/map_updates</code> 增量消息。收到地图后，它检查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>width／height</span></span>
<span class="line"><span>resolution</span></span>
<span class="line"><span>origin</span></span>
<span class="line"><span>frame_id</span></span></code></pre></div><p>对于固定窗口 Global Costmap，如果 Master Costmap 尺寸还没有锁定，它可以根据静态地图调用 <code>resizeMap()</code>，让 Master 与 <code>/map</code> 对齐。</p><p>OccupancyGrid 的 <code>0～100／-1</code> 不会原样写入内部数组，而是由 <code>interpretValue()</code> 按以下参数转换：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>track_unknown_space</span></span>
<span class="line"><span>unknown_cost_value</span></span>
<span class="line"><span>lethal_cost_threshold</span></span>
<span class="line"><span>trinary_costmap</span></span></code></pre></div><h3 id="_3-2-动态障碍也可以进入全局图" tabindex="-1">3.2 动态障碍也可以进入全局图 <a class="header-anchor" href="#_3-2-动态障碍也可以进入全局图" aria-label="Permalink to &quot;3.2 动态障碍也可以进入全局图&quot;">​</a></h3><p>Global Costmap 并不等于“只有静态地图”。只要配置 Obstacle Layer 或 Voxel Layer，它也可以融合 LaserScan 和 PointCloud2。</p><p>这让全局规划器能够绕过持续存在的动态封路区域，但代价是更高更新开销和更容易受临时观测影响。是否在 Global Costmap 中加入动态障碍，应由导航距离、传感器范围和重规划频率共同决定。</p><h3 id="_3-3-planner-不订阅-global-costmap-costmap" tabindex="-1">3.3 Planner 不订阅 <code>global_costmap/costmap</code> <a class="header-anchor" href="#_3-3-planner-不订阅-global-costmap-costmap" aria-label="Permalink to &quot;3.3 Planner 不订阅 \`global_costmap/costmap\`&quot;">​</a></h3><p>关键调用关系是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PlannerServer</span></span>
<span class="line"><span>  └─ costmap_ros_</span></span>
<span class="line"><span>      └─ LayeredCostmap</span></span>
<span class="line"><span>          └─ Master Costmap2D</span></span></code></pre></div><p>规划插件初始化时获得 Costmap ROS 对象或其底层 Costmap 指针。执行 <code>createPlan(start, goal)</code> 时直接读取进程内 Master Costmap。</p><p><code>/global_costmap/costmap</code> 主要提供给 RViz 和外部调试工具，不是 Planner Server 自己的数据回路。</p><h2 id="四、local-costmap-实时传感器怎样变成控制约束" tabindex="-1">四、Local Costmap：实时传感器怎样变成控制约束 <a class="header-anchor" href="#四、local-costmap-实时传感器怎样变成控制约束" aria-label="Permalink to &quot;四、Local Costmap：实时传感器怎样变成控制约束&quot;">​</a></h2><p>Controller Server 同样在构造阶段创建 <code>local_costmap</code>。它通常开启 <code>rolling_window</code>，窗口中心随机器人移动。</p><p><img src="`+c+`" alt="图 4：Local Costmap 到速度命令的数据流"></p><h3 id="_4-1-rolling-window-只保留机器人附近区域" tabindex="-1">4.1 Rolling Window 只保留机器人附近区域 <a class="header-anchor" href="#_4-1-rolling-window-只保留机器人附近区域" aria-label="Permalink to &quot;4.1 Rolling Window 只保留机器人附近区域&quot;">​</a></h3><p>每次更新先通过 TF 获取机器人在 Local Costmap <code>global_frame</code> 中的位姿。随后 <code>updateOrigin()</code> 移动窗口原点，同时尽量保留重叠区域中的已有代价。</p><p>滚动窗口的意义不是缩放地图，而是把固定数量的栅格持续放在机器人附近，使 Controller 能以更高频率处理近场风险。</p><h3 id="_4-2-laserscan-和-pointcloud2-先进入-observationbuffer" tabindex="-1">4.2 LaserScan 和 PointCloud2 先进入 ObservationBuffer <a class="header-anchor" href="#_4-2-laserscan-和-pointcloud2-先进入-observationbuffer" aria-label="Permalink to &quot;4.2 LaserScan 和 PointCloud2 先进入 ObservationBuffer&quot;">​</a></h3><p>Obstacle Layer 为每个 <code>observation_source</code> 创建订阅和 ObservationBuffer。</p><p>LaserScan 先经 TF Message Filter 等待坐标转换可用，再投影成 PointCloud2；原生 PointCloud2 则直接转换到目标坐标系。统一观测保存：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传感器原点</span></span>
<span class="line"><span>转换后的点云</span></span>
<span class="line"><span>障碍标记距离</span></span>
<span class="line"><span>射线清除距离</span></span>
<span class="line"><span>高度范围</span></span>
<span class="line"><span>观测有效时间</span></span></code></pre></div><h3 id="_4-3-clearing-与-marking-是两条不同路径" tabindex="-1">4.3 Clearing 与 Marking 是两条不同路径 <a class="header-anchor" href="#_4-3-clearing-与-marking-是两条不同路径" aria-label="Permalink to &quot;4.3 Clearing 与 Marking 是两条不同路径&quot;">​</a></h3><p><code>clearing: true</code> 时，从传感器原点向测量端点做 raytrace，把射线穿过的旧障碍清为自由空间。</p><p><code>marking: true</code> 时，满足距离、高度和边界条件的端点被写成 <code>LETHAL_OBSTACLE</code>。</p><p>因此动态障碍消失后能否从 Costmap 中消失，取决于新的清除射线，而不是单纯等待某个固定超时。</p><h3 id="_4-4-controller-同样直接读取内部-costmap" tabindex="-1">4.4 Controller 同样直接读取内部 Costmap <a class="header-anchor" href="#_4-4-controller-同样直接读取内部-costmap" aria-label="Permalink to &quot;4.4 Controller 同样直接读取内部 Costmap&quot;">​</a></h3><p>Controller 插件在初始化时获得 <code>local_costmap</code> 对象。每轮控制：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接收 FollowPath</span></span>
<span class="line"><span>→ 设置全局路径</span></span>
<span class="line"><span>→ 获取当前位姿</span></span>
<span class="line"><span>→ 检查 Local Costmap 是否 current</span></span>
<span class="line"><span>→ computeVelocityCommands()</span></span>
<span class="line"><span>→ 发布 cmd_vel</span></span></code></pre></div><p>轨迹打分、碰撞检查和速度约束直接读取 Local Master Costmap。外部发布的 <code>/local_costmap/costmap</code> 仍然主要服务于可视化和调试。</p><h2 id="五、一轮-costmap-更新为什么分成两阶段" tabindex="-1">五、一轮 Costmap 更新为什么分成两阶段 <a class="header-anchor" href="#五、一轮-costmap-更新为什么分成两阶段" aria-label="Permalink to &quot;五、一轮 Costmap 更新为什么分成两阶段&quot;">​</a></h2><p>Global 和 Local Costmap 使用相同的核心更新框架。</p><p><img src="`+r+'" alt="图 5：Costmap 更新、共享读取与对外发布"></p><h3 id="_5-1-updatebounds-先决定改哪里" tabindex="-1">5.1 <code>updateBounds()</code> 先决定改哪里 <a class="header-anchor" href="#_5-1-updatebounds-先决定改哪里" aria-label="Permalink to &quot;5.1 `updateBounds()` 先决定改哪里&quot;">​</a></h3><p>Layered Costmap 依次调用每个普通 Layer 和 Filter 的 <code>updateBounds()</code>，收集这轮需要更新的世界坐标范围。</p><p>Static Layer 报告地图变化范围；Obstacle Layer 报告新观测、清除射线和机器人 Footprint 范围；Inflation Layer 将边界向外扩展到膨胀半径。</p><p>最后，世界坐标边界被裁剪并转换成栅格索引窗口。</p><h3 id="_5-2-updatecosts-再决定写什么" tabindex="-1">5.2 <code>updateCosts()</code> 再决定写什么 <a class="header-anchor" href="#_5-2-updatecosts-再决定写什么" aria-label="Permalink to &quot;5.2 `updateCosts()` 再决定写什么&quot;">​</a></h3><p>普通插件按参数中的顺序写入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Static Layer</span></span>\n<span class="line"><span>→ Obstacle／Voxel Layer</span></span>\n<span class="line"><span>→ Denoise 等普通插件</span></span>\n<span class="line"><span>→ Inflation Layer</span></span></code></pre></div><p>Costmap Filter 在普通插件之后处理 combined costmap，用于 Keepout、Speed、Binary 等语义约束。</p><p>插件顺序会改变最终结果。例如 Inflation 必须看到前面已经写入的致命障碍，才能向外传播代价梯度。</p><h2 id="六、输入接口总表-数据到底从哪里进入" tabindex="-1">六、输入接口总表：数据到底从哪里进入 <a class="header-anchor" href="#六、输入接口总表-数据到底从哪里进入" aria-label="Permalink to &quot;六、输入接口总表：数据到底从哪里进入&quot;">​</a></h2><p><img src="'+d+'" alt="图 6：全局与局部地图输入输出接口矩阵"></p><h3 id="_6-1-共同基础输入" tabindex="-1">6.1 共同基础输入 <a class="header-anchor" href="#_6-1-共同基础输入" aria-label="Permalink to &quot;6.1 共同基础输入&quot;">​</a></h3><h4 id="_6-1-1-tf" tabindex="-1">6.1.1 TF <a class="header-anchor" href="#_6-1-1-tf" aria-label="Permalink to &quot;6.1.1 TF&quot;">​</a></h4><ul><li>类型：<code>tf2</code>。</li><li>作用：获取机器人位姿，转换传感器数据和 Footprint。</li></ul><h4 id="_6-1-2-footprint" tabindex="-1">6.1.2 <code>footprint</code> <a class="header-anchor" href="#_6-1-2-footprint" aria-label="Permalink to &quot;6.1.2 `footprint`&quot;">​</a></h4><ul><li>类型：<code>geometry_msgs/msg/Polygon</code>。</li><li>作用：动态更新机器人几何轮廓。</li></ul><h4 id="_6-1-3-参数中的-robot-radius-footprint" tabindex="-1">6.1.3 参数中的 <code>robot_radius／footprint</code> <a class="header-anchor" href="#_6-1-3-参数中的-robot-radius-footprint" aria-label="Permalink to &quot;6.1.3 参数中的 `robot_radius／footprint`&quot;">​</a></h4><ul><li>类型：参数。</li><li>作用：初始化机器人碰撞边界。</li></ul><h4 id="_6-1-4-filter-info" tabindex="-1">6.1.4 Filter Info <a class="header-anchor" href="#_6-1-4-filter-info" aria-label="Permalink to &quot;6.1.4 Filter Info&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/msg/CostmapFilterInfo</code>。</li><li>作用：指定 Mask Topic、过滤类型和换算参数。</li></ul><h4 id="_6-1-5-filter-mask" tabindex="-1">6.1.5 Filter Mask <a class="header-anchor" href="#_6-1-5-filter-mask" aria-label="Permalink to &quot;6.1.5 Filter Mask&quot;">​</a></h4><ul><li>类型：<code>nav_msgs/msg/OccupancyGrid</code>。</li><li>作用：描述禁行、限速或二值过滤区域。</li></ul><h3 id="_6-2-静态地图输入" tabindex="-1">6.2 静态地图输入 <a class="header-anchor" href="#_6-2-静态地图输入" aria-label="Permalink to &quot;6.2 静态地图输入&quot;">​</a></h3><h4 id="_6-2-1-map" tabindex="-1">6.2.1 <code>/map</code> <a class="header-anchor" href="#_6-2-1-map" aria-label="Permalink to &quot;6.2.1 `/map`&quot;">​</a></h4><ul><li>类型：<code>nav_msgs/msg/OccupancyGrid</code>。</li><li>消费者：Static Layer。</li></ul><h4 id="_6-2-2-map-updates" tabindex="-1">6.2.2 <code>/map_updates</code> <a class="header-anchor" href="#_6-2-2-map-updates" aria-label="Permalink to &quot;6.2.2 `/map_updates`&quot;">​</a></h4><ul><li>类型：<code>map_msgs/msg/OccupancyGridUpdate</code>。</li><li>消费者：Static Layer，可选接口。</li></ul><h4 id="_6-2-3-loadmap-服务" tabindex="-1">6.2.3 LoadMap 服务 <a class="header-anchor" href="#_6-2-3-loadmap-服务" aria-label="Permalink to &quot;6.2.3 LoadMap 服务&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/srv/LoadMap</code>。</li><li>消费者：Map Server。</li></ul><h4 id="_6-2-4-getmap-服务" tabindex="-1">6.2.4 GetMap 服务 <a class="header-anchor" href="#_6-2-4-getmap-服务" aria-label="Permalink to &quot;6.2.4 GetMap 服务&quot;">​</a></h4><ul><li>类型：<code>nav_msgs/srv/GetMap</code>。</li><li>消费者：外部地图客户端。</li></ul><h3 id="_6-3-动态障碍输入" tabindex="-1">6.3 动态障碍输入 <a class="header-anchor" href="#_6-3-动态障碍输入" aria-label="Permalink to &quot;6.3 动态障碍输入&quot;">​</a></h3><h4 id="_6-3-1-scan" tabindex="-1">6.3.1 <code>/scan</code> <a class="header-anchor" href="#_6-3-1-scan" aria-label="Permalink to &quot;6.3.1 `/scan`&quot;">​</a></h4><ul><li>类型：<code>sensor_msgs/msg/LaserScan</code>。</li><li>消费者：Obstacle Layer 或 Voxel Layer。</li></ul><h4 id="_6-3-2-点云-topic" tabindex="-1">6.3.2 点云 Topic <a class="header-anchor" href="#_6-3-2-点云-topic" aria-label="Permalink to &quot;6.3.2 点云 Topic&quot;">​</a></h4><ul><li>类型：<code>sensor_msgs/msg/PointCloud2</code>。</li><li>消费者：Obstacle Layer 或 Voxel Layer。</li></ul><h4 id="_6-3-3-range-topic" tabindex="-1">6.3.3 Range Topic <a class="header-anchor" href="#_6-3-3-range-topic" aria-label="Permalink to &quot;6.3.3 Range Topic&quot;">​</a></h4><ul><li>类型：<code>sensor_msgs/msg/Range</code>。</li><li>消费者：Range Sensor Layer。</li></ul><p>Topic 名称不是写死的，由每个 Costmap 的 <code>observation_sources</code> 参数决定。</p><h2 id="七、输出接口总表-内部地图怎样暴露给外部" tabindex="-1">七、输出接口总表：内部地图怎样暴露给外部 <a class="header-anchor" href="#七、输出接口总表-内部地图怎样暴露给外部" aria-label="Permalink to &quot;七、输出接口总表：内部地图怎样暴露给外部&quot;">​</a></h2><p>每个 Costmap 的 <code>Costmap2DPublisher</code> 通常提供：</p><h3 id="_7-1-costmap" tabindex="-1">7.1 <code>costmap</code> <a class="header-anchor" href="#_7-1-costmap" aria-label="Permalink to &quot;7.1 `costmap`&quot;">​</a></h3><ul><li>类型：<code>nav_msgs/msg/OccupancyGrid</code>。</li><li>含义：适合 RViz 显示的完整占用图。</li></ul><h3 id="_7-2-costmap-raw" tabindex="-1">7.2 <code>costmap_raw</code> <a class="header-anchor" href="#_7-2-costmap-raw" aria-label="Permalink to &quot;7.2 `costmap_raw`&quot;">​</a></h3><ul><li>类型：<code>nav2_msgs/msg/Costmap</code>。</li><li>含义：保留原始 <code>0～255</code> 代价值和元数据。</li></ul><h3 id="_7-3-costmap-updates" tabindex="-1">7.3 <code>costmap_updates</code> <a class="header-anchor" href="#_7-3-costmap-updates" aria-label="Permalink to &quot;7.3 `costmap_updates`&quot;">​</a></h3><ul><li>类型：<code>map_msgs/msg/OccupancyGridUpdate</code>。</li><li>含义：只发布发生变化的地图窗口。</li></ul><h3 id="_7-4-published-footprint" tabindex="-1">7.4 <code>published_footprint</code> <a class="header-anchor" href="#_7-4-published-footprint" aria-label="Permalink to &quot;7.4 `published_footprint`&quot;">​</a></h3><ul><li>类型：<code>geometry_msgs/msg/PolygonStamped</code>。</li><li>含义：当前机器人位姿下的外轮廓。</li></ul><h3 id="_7-5-get-costmap" tabindex="-1">7.5 <code>get_costmap</code> <a class="header-anchor" href="#_7-5-get-costmap" aria-label="Permalink to &quot;7.5 `get_costmap`&quot;">​</a></h3><ul><li>类型：<code>nav2_msgs/srv/GetCostmap</code>。</li><li>含义：按照服务请求返回当前 Costmap。</li></ul><p>清理服务由 ClearCostmapService 提供，常见接口包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clear_entirely_*_costmap</span></span>\n<span class="line"><span>clear_around_*_costmap</span></span>\n<span class="line"><span>clear_except_*_costmap</span></span></code></pre></div><p>全量清图会重置可清理 Layer，但静态层、传感器层随后会根据输入重新写回。它不是永久删除环境障碍。</p><h2 id="八、内部调用与-ros-topic-必须分开理解" tabindex="-1">八、内部调用与 ROS Topic 必须分开理解 <a class="header-anchor" href="#八、内部调用与-ros-topic-必须分开理解" aria-label="Permalink to &quot;八、内部调用与 ROS Topic 必须分开理解&quot;">​</a></h2><p>Nav2 地图链路同时存在两种完全不同的数据访问方式。</p><h3 id="_8-1-ros-接口" tabindex="-1">8.1 ROS 接口 <a class="header-anchor" href="#_8-1-ros-接口" aria-label="Permalink to &quot;8.1 ROS 接口&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Map Server → /map → Static Layer</span></span>\n<span class="line"><span>传感器 → /scan／points → Observation Layer</span></span>\n<span class="line"><span>Costmap → costmap／raw／updates → RViz 和外部工具</span></span></code></pre></div><h3 id="_8-2-进程内直接调用" tabindex="-1">8.2 进程内直接调用 <a class="header-anchor" href="#_8-2-进程内直接调用" aria-label="Permalink to &quot;8.2 进程内直接调用&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Planner Plugin → Global Costmap2D 指针</span></span>\n<span class="line"><span>Controller Plugin → Local Costmap2D 指针</span></span>\n<span class="line"><span>Goal／Progress Checker → Costmap ROS 对象</span></span></code></pre></div><p>因此排障时要先问清楚：问题发生在 ROS 消息链，还是内部共享对象更新链。</p><p><code>/global_costmap/costmap</code> 没有订阅者，不代表 Planner 没有使用 Costmap；相反，<code>/map</code> 在 RViz 显示正常，也不代表 Static Layer 已经把它正确融合进 Master Costmap。</p><h2 id="九、五类最常见的数据流断点" tabindex="-1">九、五类最常见的数据流断点 <a class="header-anchor" href="#九、五类最常见的数据流断点" aria-label="Permalink to &quot;九、五类最常见的数据流断点&quot;">​</a></h2><h3 id="_9-1-map-有数据-但-global-costmap-没静态层" tabindex="-1">9.1 <code>/map</code> 有数据，但 Global Costmap 没静态层 <a class="header-anchor" href="#_9-1-map-有数据-但-global-costmap-没静态层" aria-label="Permalink to &quot;9.1 `/map` 有数据，但 Global Costmap 没静态层&quot;">​</a></h3><p>重点检查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Static Layer 是否加载</span></span>\n<span class="line"><span>map_topic 是否正确</span></span>\n<span class="line"><span>QoS 是否匹配</span></span>\n<span class="line"><span>frame_id 是否符合预期</span></span>\n<span class="line"><span>地图尺寸是否允许 resize</span></span></code></pre></div><h3 id="_9-2-scan-有频率-但地图没有障碍" tabindex="-1">9.2 <code>/scan</code> 有频率，但地图没有障碍 <a class="header-anchor" href="#_9-2-scan-有频率-但地图没有障碍" aria-label="Permalink to &quot;9.2 `/scan` 有频率，但地图没有障碍&quot;">​</a></h3><p>重点检查传感器时间戳和 TF。Message Filter 只有在消息时间点能够完成坐标转换时，才会把数据交给 ObservationBuffer。</p><h3 id="_9-3-障碍物出现后一直不消失" tabindex="-1">9.3 障碍物出现后一直不消失 <a class="header-anchor" href="#_9-3-障碍物出现后一直不消失" aria-label="Permalink to &quot;9.3 障碍物出现后一直不消失&quot;">​</a></h3><p>确认该观测源是否开启 <code>clearing</code>，以及 <code>raytrace_max_range</code> 是否足以覆盖旧障碍。没有新的清除射线，旧标记可能继续保留。</p><h3 id="_9-4-local-costmap-正常显示-controller-却拒绝运行" tabindex="-1">9.4 Local Costmap 正常显示，Controller 却拒绝运行 <a class="header-anchor" href="#_9-4-local-costmap-正常显示-controller-却拒绝运行" aria-label="Permalink to &quot;9.4 Local Costmap 正常显示，Controller 却拒绝运行&quot;">​</a></h3><p>Controller Server 还会检查 Costmap 是否 <code>current</code>。某个配置了 <code>expected_update_rate</code> 的传感器长期不更新，可能让 Costmap 被判定为过期。</p><h3 id="_9-5-规划路径贴墙或控制器过度保守" tabindex="-1">9.5 规划路径贴墙或控制器过度保守 <a class="header-anchor" href="#_9-5-规划路径贴墙或控制器过度保守" aria-label="Permalink to &quot;9.5 规划路径贴墙或控制器过度保守&quot;">​</a></h3><p>这通常不是 Planner 或 Controller 单独的问题。应联合检查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>robot footprint</span></span>\n<span class="line"><span>footprint padding</span></span>\n<span class="line"><span>inflation radius</span></span>\n<span class="line"><span>cost scaling factor</span></span>\n<span class="line"><span>规划器的代价权重</span></span>\n<span class="line"><span>控制器的碰撞和代价权重</span></span></code></pre></div><h2 id="十、把完整链路压缩成一句话" tabindex="-1">十、把完整链路压缩成一句话 <a class="header-anchor" href="#十、把完整链路压缩成一句话" aria-label="Permalink to &quot;十、把完整链路压缩成一句话&quot;">​</a></h2><p>Nav2 地图系统的完整主链是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>YAML + 图像</span></span>\n<span class="line"><span>→ Map Server</span></span>\n<span class="line"><span>→ /map OccupancyGrid</span></span>\n<span class="line"><span>→ Static Layer</span></span>\n<span class="line"><span>→ Global／Local Layered Costmap</span></span>\n<span class="line"><span>← TF + LaserScan／PointCloud2 + Footprint + Filter</span></span>\n<span class="line"><span>→ Master Costmap2D</span></span>\n<span class="line"><span>→ Planner／Controller 进程内直接读取</span></span>\n<span class="line"><span>→ Path／cmd_vel</span></span></code></pre></div><p>Global Costmap 负责从全局视角回答“路从哪里走”，Local Costmap 负责从实时视角回答“下一步怎样安全地动”。</p><p>真正理解这两张图，关键不是记住 Topic 名字，而是分清三层边界：磁盘地图是静态资产，ROS Topic 是跨节点数据通道，Master Costmap 是规划和控制真正读取的运行时风险场。</p>',157)])])}const y=s(h,[["render",m]]);export{C as __pageData,y as default};
